{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/project-tiles.json
    The projects of ProjectGrid as tiles: cards (picture, featured badge, category and year, title, summary, tags, two links), compact cards in four columns, captions over the pictures, or a bento where the first project takes a big tile.
    Props (p): projects, labels, layout. *}
{var $v_projects = ($p['projects'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'cards')}
{var $v_over = (ui_t(ui_eq($v_layout, 'overlay')) ? true : ui_eq($v_layout, 'bento'))}
{capture $c_13}
  {foreach ui_l($v_projects) as $v_p}
    {var $v_i = $iterator->counter0}
    {capture $c_12}
      {capture $c_2}
        {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => ui_get($v_p, ['title']), 'ratio' => (ui_t(ui_eq($v_layout, 'compact')) ? '1/1' : (ui_t($v_over) ? '3/4' : '4/3')), 'className' => ui_cnv([(ui_t($v_over) ? 'h-full' : '')])]])|noescape}
        {if ui_t(ui_and([ui_get($v_p, ['featured']), !(ui_eq($v_layout, 'compact'))]))}
          {capture $c_1}
            {=ui_text(ui_get($v_labels, ['featured']))}
          {/capture}
          {=ui_include('ui/badge/badge.latte', ['p' => ['Variant' => 'default', 'Size' => 'default', 'Class' => 'absolute left-4 top-4', 'Attrs' => ui_attrs(['data-testid', 'featured'])], 'children' => $c_1])|noescape}
        {/if}
      {/capture}
      {=ui_include('ui/box/box.latte', ['p' => ['Class' => ui_s((ui_t($v_over) ? 'h-full' : 'relative'))], 'children' => $c_2])|noescape}
      {capture $c_11}
        {capture $c_3}
          {=ui_text(ui_tpl('{0}, {1}', [ui_get($v_p, ['category']), ui_get($v_p, ['year'])]))}
        {/capture}
        {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'xs', 'Class' => 'text-muted-foreground'], 'children' => $c_3])|noescape}
        {capture $c_4}
          {=ui_text(ui_get($v_p, ['title']))}
        {/capture}
        {=ui_include('ui/title/title.latte', ['p' => ['As' => ui_i(3), 'Size' => ui_s((ui_t(ui_eq($v_layout, 'compact')) ? 'sm' : 'lg')), 'Weight' => 'semibold'], 'children' => $c_4])|noescape}
        {if ui_t(!(ui_eq($v_layout, 'compact')))}
          {capture $c_5}
            {=ui_text(ui_get($v_p, ['summary']))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_5])|noescape}
        {/if}
        {if ui_t(ui_eq($v_layout, 'cards'))}
          {capture $c_7}
            {foreach ui_l(ui_get($v_p, ['tags'])) as $v_k}
              {capture $c_6}
                {=ui_text($v_k)}
              {/capture}
              {=ui_include('ui/badge/badge.latte', ['p' => ['Variant' => 'secondary', 'Size' => 'sm'], 'children' => $c_6])|noescape}
            {/foreach}
          {/capture}
          {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '2', 'Class' => 'flex-wrap'], 'children' => $c_7])|noescape}
          {capture $c_10}
            {capture $c_8}
              {=ui_text(ui_get($v_labels, ['case']))}
              {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => 'arrow-right', 'Size' => 16]])|noescape}
            {/capture}
            {=ui_include('ui/link/link.latte', ['p' => ['Href' => '#/work', 'Variant' => 'default', 'Class' => 'inline-flex items-center gap-2 text-sm font-medium'], 'children' => $c_8])|noescape}
            {capture $c_9}
              {=ui_text(ui_get($v_labels, ['view']))}
              {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => 'external-link', 'Size' => 16]])|noescape}
            {/capture}
            {=ui_include('ui/link/link.latte', ['p' => ['Href' => '#/work', 'Variant' => 'default', 'Class' => 'inline-flex items-center gap-2 text-sm font-medium'], 'children' => $c_9])|noescape}
          {/capture}
          {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '4', 'Class' => 'pt-2'], 'children' => $c_10])|noescape}
        {/if}
      {/capture}
      {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2', 'Align' => 'stretch', 'Class' => ui_s((ui_t($v_over) ? 'absolute right-4 bottom-4 left-4 rounded bg-background p-4' : ''))], 'children' => $c_11])|noescape}
    {/capture}
    {=ui_include('blocks/article-block.latte', ['p' => ['className' => ui_cnv([ui_cnv(['flex flex-col gap-4', (ui_t($v_over) ? 'relative' : 'rounded bg-card inset-ring inset-ring-border p-4'), (ui_t(ui_and([ui_eq($v_layout, 'bento'), ui_eq($v_i, 0)])) ? 'sm:col-span-2 lg:row-span-2' : '')])]), 'testid' => 'item'], 'children' => $c_12])|noescape}
  {/foreach}
{/capture}
{=ui_include('ui/box/box.latte', ['p' => ['Class' => ui_s((ui_t(ui_eq($v_layout, 'compact')) ? 'grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4' : 'grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3')), 'Attrs' => ui_attrs(['data-testid', 'items'])], 'children' => $c_13])|noescape}
